    96→	}
    97→	r, s, _ := decodeSignature(sig)
    98→	return SetCodeAuthorization{
    99→		ChainID: auth.ChainID,
   100→		Address: auth.Address,
   101→		Nonce:   auth.Nonce,
   102→		V:       sig[64],
   103→		R:       *uint256.MustFromBig(r),
   104→		S:       *uint256.MustFromBig(s),
   105→	}, nil
   106→}
