   117→// Authority recovers the the authorizing account of an authorization.
   118→func (a *SetCodeAuthorization) Authority() (common.Address, error) {
   119→	sighash := a.SigHash()
   120→	if !crypto.ValidateSignatureValues(a.V, a.R.ToBig(), a.S.ToBig(), true) {
   121→		return common.Address{}, ErrInvalidSig
   122→	}
   123→	// encode the signature in uncompressed format
   124→	var sig [crypto.SignatureLength]byte
   125→	a.R.WriteToSlice(sig[:32])
   126→	a.S.WriteToSlice(sig[32:64])
   127→	sig[64] = a.V
   128→	// recover the public key from the signature
   129→	pub, err := crypto.Ecrecover(sighash[:], sig[:])
   130→	if err != nil {
   131→		return common.Address{}, err
   132→	}
   133→	if len(pub) == 0 || pub[0] != 4 {
   134→		return common.Address{}, errors.New("invalid public key")
   135→	}
   136→	var addr common.Address
   137→	copy(addr[:], crypto.Keccak256(pub[1:])[12:])
   138→	return addr, nil
   139→}
