   103→	} else {
   104→		account.Root = common.BytesToHash(slim.Root)
   105→	}
   106→	if len(slim.CodeHash) == 0 {
   107→		account.CodeHash = EmptyCodeHash[:]
   108→	} else {
   109→		account.CodeHash = slim.CodeHash
   110→	}
   111→	return &account, nil
   112→}
   113→
   114→// FullAccountRLP converts data on the 'slim RLP' format into the full RLP-format.
   115→func FullAccountRLP(data []byte) ([]byte, error) {
   116→	account, err := FullAccount(data)
   117→	if err != nil {
   118→		return nil, err
   119→	}
   120→	return rlp.EncodeToBytes(account)
   121→}
