    42→// EncodeNonce converts the given integer to a block nonce.
    43→func EncodeNonce(i uint64) BlockNonce {
    44→	var n BlockNonce
    45→	binary.BigEndian.PutUint64(n[:], i)
    46→	return n
    47→}
