   131→var headerSize = common.StorageSize(reflect.TypeFor[Header]().Size())
   132→
   133→// Size returns the approximate memory used by all internal contents. It is used
   134→// to approximate and limit the memory consumption of various caches.
   135→func (h *Header) Size() common.StorageSize {
   136→	var baseFeeBits int
   137→	if h.BaseFee != nil {
   138→		baseFeeBits = h.BaseFee.BitLen()
   139→	}
   140→	return headerSize + common.StorageSize(len(h.Extra)+(h.Difficulty.BitLen()+h.Number.BitLen()+baseFeeBits)/8)
   141→}
   142→
   143→// SanityCheck checks a few basic things -- these checks are way beyond what
   144→// any 'sane' production values should hold, and can mainly be used to prevent
   145→// that the unbounded fields are stuffed with junk data to add processing
   146→// overhead
   147→func (h *Header) SanityCheck() error {
   148→	if h.Number != nil && !h.Number.IsUint64() {
   149→		return fmt.Errorf("too large block number: bitlen %d", h.Number.BitLen())
   150→	}
   151→	if h.Difficulty != nil {
   152→		if diffLen := h.Difficulty.BitLen(); diffLen > 80 {
   153→			return fmt.Errorf("too large block difficulty: bitlen %d", diffLen)
   154→		}
   155→	}
   156→	if eLen := len(h.Extra); eLen > 100*1024 {
   157→		return fmt.Errorf("too large block extradata: size %d", eLen)
   158→	}
   159→	if h.BaseFee != nil {
   160→		if bfLen := h.BaseFee.BitLen(); bfLen > 256 {
   161→			return fmt.Errorf("too large base fee: bitlen %d", bfLen)
   162→		}
   163→	}
   164→	return nil
   165→}
