   296→// CopyHeader creates a deep copy of a block header.
   297→func CopyHeader(h *Header) *Header {
   298→	cpy := *h
   299→	if cpy.Difficulty = new(big.Int); h.Difficulty != nil {
   300→		cpy.Difficulty.Set(h.Difficulty)
   301→	}
   302→	if cpy.Number = new(big.Int); h.Number != nil {
   303→		cpy.Number.Set(h.Number)
   304→	}
   305→	if h.BaseFee != nil {
   306→		cpy.BaseFee = new(big.Int).Set(h.BaseFee)
   307→	}
   308→	if len(h.Extra) > 0 {
   309→		cpy.Extra = make([]byte, len(h.Extra))
   310→		copy(cpy.Extra, h.Extra)
   311→	}
   312→	if h.WithdrawalsHash != nil {
   313→		cpy.WithdrawalsHash = new(common.Hash)
   314→		*cpy.WithdrawalsHash = *h.WithdrawalsHash
   315→	}
   316→	if h.ExcessBlobGas != nil {
   317→		cpy.ExcessBlobGas = new(uint64)
   318→		*cpy.ExcessBlobGas = *h.ExcessBlobGas
   319→	}
   320→	if h.BlobGasUsed != nil {
   321→		cpy.BlobGasUsed = new(uint64)
   322→		*cpy.BlobGasUsed = *h.BlobGasUsed
   323→	}
   324→	if h.ParentBeaconRoot != nil {
   325→		cpy.ParentBeaconRoot = new(common.Hash)
   326→		*cpy.ParentBeaconRoot = *h.ParentBeaconRoot
   327→	}
   328→	if h.RequestsHash != nil {
   329→		cpy.RequestsHash = new(common.Hash)
   330→		*cpy.RequestsHash = *h.RequestsHash
   331→	}
   332→	return &cpy
   333→}
