   335→// DecodeRLP decodes a block from RLP.
   336→func (b *Block) DecodeRLP(s *rlp.Stream) error {
   337→	var eb extblock
   338→	_, size, _ := s.Kind()
   339→	if err := s.Decode(&eb); err != nil {
   340→		return err
   341→	}
   342→	b.header, b.uncles, b.transactions, b.withdrawals = eb.Header, eb.Uncles, eb.Txs, eb.Withdrawals
   343→	b.size.Store(rlp.ListSize(size))
   344→	return nil
   345→}
