   467→// CalcRequestsHash creates the block requestsHash value for a list of requests.
   468→func CalcRequestsHash(requests [][]byte) common.Hash {
   469→	h1, h2 := sha256.New(), sha256.New()
   470→	var buf common.Hash
   471→	for _, item := range requests {
   472→		if len(item) > 1 { // skip items with only requestType and no data.
   473→			h1.Reset()
   474→			h1.Write(item)
   475→			h2.Write(h1.Sum(buf[:0]))
   476→		}
   477→	}
   478→	h2.Sum(buf[:0])
   479→	return buf
   480→}
