   544→	listContent, _, err := rlp.SplitList(header)
   545→	if err != nil {
   546→		return common.Hash{}
   547→	}
   548→	parentHash, _, err := rlp.SplitString(listContent)
   549→	if err != nil {
   550→		return common.Hash{}
   551→	}
   552→	if len(parentHash) != 32 {
   553→		return common.Hash{}
   554→	}
