    79→	copy() TxData // creates a deep copy and initializes all fields
    80→
    81→	chainID() *big.Int
    82→	accessList() AccessList
    83→	data() []byte
    84→	gas() uint64
    85→	gasPrice() *big.Int
    86→	gasTipCap() *big.Int
    87→	gasFeeCap() *big.Int
    88→	value() *big.Int
    89→	nonce() uint64
    90→	to() *common.Address
    91→
    92→	rawSignatureValues() (v, r, s *big.Int)
    93→	setSignatureValues(chainID, v, r, s *big.Int)
    94→
    95→	// effectiveGasPrice computes the gas price paid by the transaction, given
    96→	// the inclusion block baseFee.
    97→	//
    98→	// Unlike other TxData methods, the returned *big.Int should be an independent
    99→	// copy of the computed value, i.e. callers are allowed to mutate the result.
   100→	// Method implementations can use 'dst' to store the result.
   101→	effectiveGasPrice(dst *big.Int, baseFee *big.Int) *big.Int
   102→
   103→	encode(*bytes.Buffer) error
   104→	decode([]byte) error
   105→
   106→	// sigHash returns the hash of the transaction that is ought to be signed
   107→	sigHash(*big.Int) common.Hash
   108→}
