   110→// EncodeRLP implements rlp.Encoder
   111→func (tx *Transaction) EncodeRLP(w io.Writer) error {
   112→	if tx.Type() == LegacyTxType {
   113→		return rlp.Encode(w, tx.inner)
   114→	}
   115→	// It's an EIP-2718 typed TX envelope.
   116→	buf := encodeBufferPool.Get().(*bytes.Buffer)
   117→	defer encodeBufferPool.Put(buf)
   118→	buf.Reset()
   119→	if err := tx.encodeTyped(buf); err != nil {
   120→		return err
   121→	}
   122→	return rlp.Encode(w, buf.Bytes())
   123→}
   124→
   125→// encodeTyped writes the canonical encoding of a typed transaction to w.
   126→func (tx *Transaction) encodeTyped(w *bytes.Buffer) error {
   127→	w.WriteByte(tx.Type())
   128→	return tx.inner.encode(w)
   129→}
