   131→// MarshalBinary returns the canonical encoding of the transaction.
   132→// For legacy transactions, it returns the RLP encoding. For EIP-2718 typed
   133→// transactions, it returns the type and payload.
   134→func (tx *Transaction) MarshalBinary() ([]byte, error) {
   135→	if tx.Type() == LegacyTxType {
   136→		return rlp.EncodeToBytes(tx.inner)
   137→	}
   138→	var buf bytes.Buffer
   139→	err := tx.encodeTyped(&buf)
   140→	return buf.Bytes(), err
   141→}
   142→
   143→// DecodeRLP implements rlp.Decoder
   144→func (tx *Transaction) DecodeRLP(s *rlp.Stream) error {
   145→	kind, size, err := s.Kind()
   146→	switch {
   147→	case err != nil:
   148→		return err
   149→	case kind == rlp.List:
   150→		// It's a legacy transaction.
   151→		var inner LegacyTx
   152→		err := s.Decode(&inner)
   153→		if err == nil {
   154→			tx.setDecoded(&inner, rlp.ListSize(size))
   155→		}
   156→		return err
   157→	case kind == rlp.Byte:
   158→		return errShortTypedTx
   159→	default:
   160→		// It's an EIP-2718 typed TX envelope.
   161→		// First read the tx payload bytes into a temporary buffer.
   162→		b, buf, err := getPooledBuffer(size)
   163→		if err != nil {
   164→			return err
   165→		}
   166→		defer encodeBufferPool.Put(buf)
   167→		if err := s.ReadBytes(b); err != nil {
   168→			return err
   169→		}
   170→		// Now decode the inner transaction.
   171→		inner, err := tx.decodeTyped(b)
   172→		if err == nil {
   173→			tx.setDecoded(inner, size)
   174→		}
   175→		return err
   176→	}
   177→}
   178→
   179→// UnmarshalBinary decodes the canonical encoding of transactions.
   180→// It supports legacy RLP transactions and EIP-2718 typed transactions.
   181→func (tx *Transaction) UnmarshalBinary(b []byte) error {
   182→	if len(b) > 0 && b[0] > 0x7f {
   183→		// It's a legacy transaction.
   184→		var data LegacyTx
   185→		err := rlp.DecodeBytes(b, &data)
   186→		if err != nil {
   187→			return err
   188→		}
   189→		tx.setDecoded(&data, uint64(len(b)))
   190→		return nil
   191→	}
   192→	// It's an EIP-2718 typed transaction envelope.
   193→	inner, err := tx.decodeTyped(b)
   194→	if err != nil {
   195→		return err
   196→	}
   197→	tx.setDecoded(inner, uint64(len(b)))
   198→	return nil
   199→}
   200→
   201→// decodeTyped decodes a typed transaction from the canonical format.
   202→func (tx *Transaction) decodeTyped(b []byte) (TxData, error) {
   203→	if len(b) <= 1 {
   204→		return nil, errShortTypedTx
   205→	}
   206→	var inner TxData
   207→	switch b[0] {
   208→	case AccessListTxType:
   209→		inner = new(AccessListTx)
   210→	case DynamicFeeTxType:
   211→		inner = new(DynamicFeeTx)
   212→	case BlobTxType:
   213→		inner = new(BlobTx)
   214→	case SetCodeTxType:
   215→		inner = new(SetCodeTx)
   216→	default:
   217→		return nil, ErrTxTypeNotSupported
   218→	}
   219→	err := inner.decode(b[1:])
   220→	return inner, err
   221→}
   222→
   223→// setDecoded sets the inner transaction and size after decoding.
   224→func (tx *Transaction) setDecoded(inner TxData, size uint64) {
   225→	tx.inner = inner
   226→	tx.time = time.Now()
   227→	if size > 0 {
   228→		tx.size.Store(size)
   229→	}
   230→}
