   232→func sanityCheckSignature(v *big.Int, r *big.Int, s *big.Int, maybeProtected bool) error {
   233→	if isProtectedV(v) && !maybeProtected {
   234→		return ErrUnexpectedProtection
   235→	}
   236→
   237→	var plainV byte
   238→	if isProtectedV(v) {
   239→		chainID := deriveChainId(v).Uint64()
   240→		plainV = byte(v.Uint64() - 35 - 2*chainID)
   241→	} else if maybeProtected {
   242→		// Only EIP-155 signatures can be optionally protected. Since
   243→		// we determined this v value is not protected, it must be a
   244→		// raw 27 or 28.
   245→		plainV = byte(v.Uint64() - 27)
   246→	} else {
   247→		// If the signature is not optionally protected, we assume it
   248→		// must already be equal to the recovery id.
   249→		plainV = byte(v.Uint64())
   250→	}
   251→	if !crypto.ValidateSignatureValues(plainV, r, s, false) {
   252→		return ErrInvalidSig
   253→	}
   254→
   255→	return nil
   256→}
   257→
   258→func isProtectedV(V *big.Int) bool {
   259→	if V.BitLen() <= 8 {
   260→		v := V.Uint64()
   261→		return v != 27 && v != 28 && v != 1 && v != 0
   262→	}
   263→	// anything not 27 or 28 is considered protected
   264→	return true
   265→}
   266→
   267→// Protected says whether the transaction is replay-protected.
   268→func (tx *Transaction) Protected() bool {
   269→	switch tx := tx.inner.(type) {
   270→	case *LegacyTx:
   271→		return tx.V != nil && isProtectedV(tx.V)
   272→	default:
   273→		return true
   274→	}
   275→}
