   356→// EffectiveGasTip returns the effective miner gasTipCap for the given base fee.
   357→// Note: if the effective gasTipCap would be negative, this method
   358→// returns ErrGasFeeCapTooLow, and value is undefined.
   359→func (tx *Transaction) EffectiveGasTip(baseFee *big.Int) (*big.Int, error) {
   360→	dst := new(uint256.Int)
   361→	base := new(uint256.Int)
   362→	if baseFee != nil {
   363→		if base.SetFromBig(baseFee) {
   364→			return nil, ErrUint256Overflow
   365→		}
   366→	}
   367→	err := tx.calcEffectiveGasTip(dst, base)
   368→	return dst.ToBig(), err
   369→}
   370→
   371→// calcEffectiveGasTip calculates the effective gas tip of the transaction and
   372→// saves the result to dst.
   373→func (tx *Transaction) calcEffectiveGasTip(dst *uint256.Int, baseFee *uint256.Int) error {
   374→	if baseFee == nil {
   375→		if dst.SetFromBig(tx.inner.gasTipCap()) {
   376→			return ErrUint256Overflow
   377→		}
   378→		return nil
   379→	}
   380→
   381→	var err error
   382→	if dst.SetFromBig(tx.inner.gasFeeCap()) {
   383→		return ErrUint256Overflow
   384→	}
   385→	if dst.Cmp(baseFee) < 0 {
   386→		err = ErrGasFeeCapTooLow
   387→	}
   388→
   389→	dst.Sub(dst, baseFee)
   390→	gasTipCap := new(uint256.Int)
   391→	if gasTipCap.SetFromBig(tx.inner.gasTipCap()) {
   392→		return ErrUint256Overflow
   393→	}
   394→	if gasTipCap.Cmp(dst) < 0 {
   395→		dst.Set(gasTipCap)
   396→	}
   397→	return err
   398→}
   399→
   400→func (tx *Transaction) EffectiveGasTipCmp(other *Transaction, baseFee *uint256.Int) int {
   401→	if baseFee == nil {
   402→		return tx.GasTipCapCmp(other)
   403→	}
   404→	// Use more efficient internal method.
   405→	txTip, otherTip := new(uint256.Int), new(uint256.Int)
   406→	tx.calcEffectiveGasTip(txTip, baseFee)
   407→	other.calcEffectiveGasTip(otherTip, baseFee)
   408→	return txTip.Cmp(otherTip)
   409→}
