   411→// EffectiveGasTipIntCmp compares the effective gasTipCap of a transaction to the given gasTipCap.
   412→func (tx *Transaction) EffectiveGasTipIntCmp(other *uint256.Int, baseFee *uint256.Int) int {
   413→	if baseFee == nil {
   414→		return tx.GasTipCapIntCmp(other.ToBig())
   415→	}
   416→	txTip := new(uint256.Int)
   417→	tx.calcEffectiveGasTip(txTip, baseFee)
   418→	return txTip.Cmp(other)
   419→}
