   463→// WithoutBlobTxSidecar returns a copy of tx with the blob sidecar removed.
   464→func (tx *Transaction) WithoutBlobTxSidecar() *Transaction {
   465→	blobtx, ok := tx.inner.(*BlobTx)
   466→	if !ok || blobtx.Sidecar == nil {
   467→		return tx
   468→	}
   469→	cpy := &Transaction{
   470→		inner: blobtx.withoutSidecar(),
   471→		time:  tx.time,
   472→	}
   473→	if size := tx.size.Load(); size != 0 {
   474→		// The tx had a sidecar before, so we need to subtract it from the size.
   475→		scSize := rlp.ListSize(blobtx.Sidecar.encodedSize())
   476→		cpy.size.Store(size - scSize)
   477→	}
   478→	if h := tx.hash.Load(); h != nil {
   479→		cpy.hash.Store(h)
   480→	}
   481→	if f := tx.from.Load(); f != nil {
   482→		cpy.from.Store(f)
   483→	}
   484→	return cpy
   485→}
