   519→	setcodetx, ok := tx.inner.(*SetCodeTx)
   520→	if !ok {
   521→		return nil
   522→	}
   523→	var (
   524→		marks = make(map[common.Address]bool)
   525→		auths = make([]common.Address, 0, len(setcodetx.AuthList))
   526→	)
   527→	for _, auth := range setcodetx.AuthList {
   528→		if addr, err := auth.Authority(); err == nil {
   529→			if marks[addr] {
   530→				continue
   531→			}
   532→			marks[addr] = true
   533→			auths = append(auths, addr)
   534→		}
   535→	}
   536→	return auths
   537→}
