   568→// Size returns the true encoded storage size of the transaction, either by encoding
   569→// and returning it, or returning a previously cached value.
   570→func (tx *Transaction) Size() uint64 {
   571→	if size := tx.size.Load(); size > 0 {
   572→		return size
   573→	}
   574→
   575→	// Cache miss, encode and cache.
   576→	// Note we rely on the assumption that all tx.inner values are RLP-encoded!
   577→	c := writeCounter(0)
   578→	rlp.Encode(&c, &tx.inner)
   579→	size := uint64(c)
   580→
   581→	// For blob transactions, add the size of the blob content and the outer list of the
   582→	// tx + sidecar encoding.
   583→	if sc := tx.BlobTxSidecar(); sc != nil {
   584→		size += rlp.ListSize(sc.encodedSize())
   585→	}
   586→
   587→	// For typed transactions, the encoding also includes the leading type byte.
   588→	if tx.Type() != LegacyTxType {
   589→		size += 1
   590→	}
   591→
   592→	tx.size.Store(size)
   593→	return size
   594→}
