   596→// WithSignature returns a new transaction with the given signature.
   597→// This signature needs to be in the [R || S || V] format where V is 0 or 1.
   598→func (tx *Transaction) WithSignature(signer Signer, sig []byte) (*Transaction, error) {
   599→	r, s, v, err := signer.SignatureValues(tx, sig)
   600→	if err != nil {
   601→		return nil, err
   602→	}
   603→	if r == nil || s == nil || v == nil {
   604→		return nil, fmt.Errorf("%w: r: %s, s: %s, v: %s", ErrInvalidSig, r, s, v)
   605→	}
   606→	cpy := tx.inner.copy()
   607→	cpy.setSignatureValues(signer.ChainID(), v, r, s)
   608→	return &Transaction{inner: cpy, time: tx.time}, nil
   609→}
