   611→// Transactions implements DerivableList for transactions.
   612→type Transactions []*Transaction
   613→
   614→// Len returns the length of s.
   615→func (s Transactions) Len() int { return len(s) }
   616→
   617→// EncodeIndex encodes the i'th transaction to w. Note that this does not check for errors
   618→// because we assume that *Transaction will only ever contain valid txs that were either
   619→// constructed by decoding or via public API in this package.
   620→func (s Transactions) EncodeIndex(i int, w *bytes.Buffer) {
   621→	tx := s[i]
   622→	if tx.Type() == LegacyTxType {
   623→		rlp.Encode(w, tx.inner)
   624→	} else {
   625→		tx.encodeTyped(w)
   626→	}
   627→}
   628→
   629→// TxDifference returns a new set of transactions that are present in a but not in b.
   630→func TxDifference(a, b Transactions) Transactions {
   631→	keep := make(Transactions, 0, len(a))
   632→
   633→	remove := make(map[common.Hash]struct{}, b.Len())
   634→	for _, tx := range b {
   635→		remove[tx.Hash()] = struct{}{}
   636→	}
   637→
   638→	for _, tx := range a {
   639→		if _, ok := remove[tx.Hash()]; !ok {
   640→			keep = append(keep, tx)
   641→		}
   642→	}
   643→
   644→	return keep
   645→}
   646→
   647→// HashDifference returns a new set of hashes that are present in a but not in b.
   648→func HashDifference(a, b []common.Hash) []common.Hash {
   649→	keep := make([]common.Hash, 0, len(a))
   650→
   651→	remove := make(map[common.Hash]struct{})
   652→	for _, hash := range b {
   653→		remove[hash] = struct{}{}
   654→	}
   655→
   656→	for _, hash := range a {
